pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        vm.assume(from != address(0));
        // Deploy an adversarial callee that always reverts
        Reverter reverter = new Reverter();
        // Ensure the target caddress is the adversarial reverter
        // but the fuzzer still supplies the original caddress; we override it here
        // to route through the failing helper. The remaining parameters (from, _tos, v)
        // are fully fuzzed.
        bool ok;
        try c.transfer(from, address(reverter), _tos, v) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference C: every sub-call through the reverting helper reverts the whole transaction,
        // so ok MUST be false. The buggy version silently ignores failures and returns true.
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

