contract Reverter {
    function () external payable {
        if (msg.data.length >= 4) {
            bytes4 selector;
            assembly {
                calldatacopy(0, 0, 4)
                selector := mload(0)
            }
            assembly {
                let free_mem_ptr := mload(0x40)
                mstore(free_mem_ptr, selector)
                revert(free_mem_ptr, 4)
            }
        } else {
            revert("no selector");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        // Assume admissible inputs: tos array non-empty and caddress != address(c) to avoid self-call edge cases
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(c));
        // Deploy a callee that accepts only the transferFrom selector, reverting on anything else
        TransferFromOnlyCallee callee = new TransferFromOnlyCallee();
        vm.prank(from);
        c.transfer(from, address(callee), _tos, v);
        // After the call, the callee must have been invoked with transferFrom selector,
        // which is only true for the reference contract. The mutant uses transfer selector and will revert.
        // The callee exposes a flag indicating whether the correct selector was seen.
        assertTrue(callee.transferFromCalled());
    }
}

contract TransferFromOnlyCallee {
    bool public transferFromCalled;
    // Accept only calls with transferFrom selector; revert for any other selector
    fallback(bytes calldata data) external returns (bytes memory) {
        if (bytes4(data) == 0x23b872dd) {
            transferFromCalled = true;
            return "";
        }
        revert("Unknown selector");
    }
}

